Database.Load:
      var index = 0;
	  var customerPKey = "";
	  var secretariaPKey = "";
      var additionalCond = "";

	  if(Utils.isDefined(jsonQuery.customerPKey)){
        customerPKey =  Utils.convertForDBParam(jsonQuery.customerPKey, "DomPKey");
        additionalCond += "AND cgf_Secretarias__c.cgf_Cuenta__c = #customerPKey# ";
	  }
	  if(Utils.isDefined(jsonQuery.secretariaPKey)){
        secretariaPKey = Utils.convertForDBParam(jsonQuery.secretariaPKey, "DomPKey");
        additionalCond += "AND cgf_Secretarias__c.Id = #secretariaPKey# ";
      }

      var sqlParams = {customerPKey, secretariaPKey};

      var sqlStmt = "SELECT ";
      sqlStmt += "cgf_Secretarias__c.Id AS pKey, ";
      sqlStmt += "cgf_Secretarias__c.Name AS secretariaName, ";
      sqlStmt += "cgf_Secretarias__c.cgf_Cuenta__c AS customerPKey, ";
      sqlStmt += "cgf_Secretarias__c.Id as secretariaPKey, ";
      sqlStmt += "cgf_Secretarias__c.cgf_Email__c as secretariaEmail, ";
      sqlStmt += "cgf_Secretarias__c.cgf_Telefono__c as secretariaTelefono, ";
      sqlStmt += "cgf_Secretarias__c.Id AS bpaSecretariaPKey ";
      sqlStmt += "FROM cgf_Secretarias__c ";
      sqlStmt += "WHERE ";
      sqlStmt += "cgf_Secretarias__c.IsDeleted = '0' ";
      sqlStmt += additionalCond;

      return Utils.replaceMacrosParam(sqlStmt, sqlParams);
